customers = [(3, 100), (4, 500), (1, 200), (1, 700)]

def label(orders, recency):
    if orders >= 2:
        return 'active repeat' if recency <= 365 else 'lapsed repeat'
    return 'recent single' if recency <= 365 else 'lapsed single'

for o, r in customers:
    print(label(o, r))
